<?php requirePermission('inventory');
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$action=$_POST['action']??'';
 if($action==='adjust'){$pid=(int)$_POST['product_id'];$new=max(0,(int)$_POST['new_stock']);$reason=trim($_POST['reason']??'Ajuste manual');try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT stock,name FROM products WHERE id=? FOR UPDATE');$st->execute([$pid]);$p=$st->fetch();if(!$p)throw new Exception('Produto não encontrado.');$diff=$new-(int)$p['stock'];$pdo->prepare('UPDATE products SET stock=? WHERE id=?')->execute([$new,$pid]);if($diff!==0)$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,type,quantity,reference,notes) VALUES(?,? ,"adjustment",?,"INVENTORY",?)')->execute([$pid,$_SESSION['user']['id'],$diff,$reason]);audit($pdo,'adjust','product',$pid,'Estoque '.$p['stock'].' → '.$new.'. '.$reason);$pdo->commit();flash('success','Estoque ajustado.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('index.php?page=inventory');}
}
$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT * FROM products WHERE active=1 AND (name LIKE ? OR sku LIKE ? OR barcode LIKE ?) ORDER BY name');$st->execute(["%$q%","%$q%","%$q%"]);$products=$st->fetchAll();$mov=$pdo->query('SELECT sm.*,p.name product,u.name user_name FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN users u ON u.id=sm.user_id ORDER BY sm.id DESC LIMIT 40')->fetchAll();$title='Inventário';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Inventário e ajustes</h1><p>Conferência rápida, divergências e histórico de movimentação.</p></div></div>
<section class="panel"><form class="search"><input name="q" placeholder="Produto, SKU ou código de barras" value="<?=e($q)?>" autofocus><button class="btn">Localizar</button></form><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Código</th><th>Saldo</th><th>Mín.</th><th>Local</th><th>Novo saldo</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><strong><?=e($p['name'])?></strong><small><?=e($p['sku'])?></small></td><td><?=e($p['barcode']?:'-')?></td><td><span class="badge <?=$p['stock']<=$p['min_stock']?'danger':'ok'?>"><?=$p['stock']?></span></td><td><?=$p['min_stock']?></td><td><?=e($p['location']?:'-')?></td><td><form method="post" class="inline-adjust"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="adjust"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="number" name="new_stock" min="0" value="<?=$p['stock']?>" required><input name="reason" placeholder="Motivo" required><button class="btn">Ajustar</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Últimas movimentações</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Qtd.</th><th>Referência</th><th>Usuário</th></tr></thead><tbody><?php foreach($mov as $m):?><tr><td><?=date('d/m/Y H:i',strtotime($m['created_at']))?></td><td><?=e($m['product'])?></td><td><?=e($m['type'])?></td><td class="<?=$m['quantity']>=0?'kpi-positive':'kpi-negative'?>"><?=$m['quantity']>0?'+':''?><?=$m['quantity']?></td><td><?=e($m['reference'])?><small><?=e($m['notes'])?></small></td><td><?=e($m['user_name'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../../includes/footer.php';?>
